import {
  referenceProvider,
  type ReferenceProvider,
} from '../../types/reference-connectors';
import { createHash, randomUUID } from 'crypto';
import { eq } from 'drizzle-orm';
import { z } from 'zod';
import { transaction, type openDurableDatabase } from '../library/database';
import {
  referenceDiscoveries,
  referencePlans,
  referenceOnboarding,
  connectorOnboarding,
  plannedSources,
} from './planSchema';
import { sources } from './schema';
import {
  REFERENCE_PLAN_BYTES,
  REFERENCE_PLAN_LIMIT,
  REFERENCE_PLAN_LIFETIME_MS,
  REFERENCE_REMINDER_DELAY_MS,
  ReferenceDiscoveryInputSchema,
  ReferenceDiscoverySchema,
  ReferencePlanInputSchema,
  ReferencePlanSchema,
  type ReferenceImportPlan,
  type ReferenceOnboardingAction,
} from '../../types/reference-onboarding';

type Database = Awaited<ReturnType<typeof openDurableDatabase>>;

export class ProfilePlans {
  constructor(private readonly db: Database) {}

  backfillApprovedCollections(): void {
    const unrecorded = this.db
      .select()
      .from(plannedSources)
      .all()
      .filter((row) => row.collectionIds.length === 0);
    if (!unrecorded.length) return;
    const approved = this.db
      .select()
      .from(referencePlans)
      .all()
      .map((row) => row.body)
      .filter((plan) => plan.approvedAt)
      .sort((left, right) =>
        (right.approvedAt ?? '').localeCompare(left.approvedAt ?? ''),
      );
    transaction(this.db, () => {
      for (const row of unrecorded) {
        const approval = approved
          .filter((plan) => plan.discoveryId === row.discoveryId)
          .flatMap((plan) => plan.sources)
          .find((source) => source.collection.id === row.collectionId);
        this.db
          .update(plannedSources)
          .set({ collectionIds: approval?.collectionIds ?? [row.collectionId] })
          .where(eq(plannedSources.sourceId, row.sourceId))
          .run();
      }
    });
  }

  initializeOnboarding(): void {
    const preference = this.db.select().from(referenceOnboarding).get();
    if (preference)
      this.db
        .insert(connectorOnboarding)
        .values({
          provider: 'cosmos',
          state: preference.state,
          offeredAt: preference.offeredAt,
          remindAt: preference.remindAt,
        })
        .onConflictDoNothing()
        .run();
  }

  saveDiscovery(input: z.input<typeof ReferenceDiscoveryInputSchema>) {
    const parsed = ReferenceDiscoveryInputSchema.parse(input);
    if (
      parsed.total !== parsed.collections.length ||
      new Set(parsed.collections.map((item) => item.id)).size !== parsed.total
    )
      throw new Error('Incomplete profile collection discovery');
    const discovery = ReferenceDiscoverySchema.parse({
      ...parsed,
      id: randomUUID(),
      createdAt: new Date().toISOString(),
    });
    this.db
      .insert(referenceDiscoveries)
      .values({ id: discovery.id, body: discovery })
      .run();
    return discovery;
  }

  discovery(id: string) {
    const record = this.db
      .select()
      .from(referenceDiscoveries)
      .where(eq(referenceDiscoveries.id, id))
      .get();
    if (!record) throw new Error('Unknown reference discovery');
    return ReferenceDiscoverySchema.parse(record.body);
  }

  discoveries() {
    return this.db
      .select()
      .from(referenceDiscoveries)
      .all()
      .map((record) => ReferenceDiscoverySchema.parse(record.body));
  }

  savePlan(input: z.input<typeof ReferencePlanInputSchema>) {
    const parsed = ReferencePlanInputSchema.parse(input);
    const discovery = this.discovery(parsed.discoveryId);
    const available = new Set(
      discovery.collections.map((collection) => collection.id),
    );
    if (
      parsed.sources.some((source) => !available.has(source.collection.id)) ||
      new Set(parsed.sources.map((source) => source.collection.id)).size !==
        parsed.sources.length
    )
      throw new Error('Choose each collection from this discovery only once');
    if (
      parsed.sources.some((source) =>
        source.references.some(
          (reference) =>
            reference.provider !== referenceProvider(discovery.profile),
        ),
      )
    )
      throw new Error(
        'Reference provider does not match the discovered account',
      );
    const unique = new Set(
      parsed.sources.flatMap((source) =>
        source.references.map((reference) => reference.remoteId),
      ),
    );
    if (
      unique.size > REFERENCE_PLAN_LIMIT ||
      parsed.reusableCount > unique.size
    )
      throw new Error(
        'Reference plan exceeds its coverage limit; select fewer collections',
      );
    const body = JSON.stringify(parsed);
    if (Buffer.byteLength(body) > REFERENCE_PLAN_BYTES)
      throw new Error('Reference plan is too large; select fewer collections');
    const plan = ReferencePlanSchema.parse({
      ...parsed,
      id: randomUUID(),
      profile: discovery.profile,
      revision: createHash('sha256').update(body).digest('hex'),
      createdAt: new Date().toISOString(),
      expiresAt: new Date(
        Date.now() + REFERENCE_PLAN_LIFETIME_MS,
      ).toISOString(),
      approvedAt: null,
      jobIds: [],
    });
    this.db.insert(referencePlans).values({ id: plan.id, body: plan }).run();
    return plan;
  }

  plan(id: string) {
    const record = this.db
      .select()
      .from(referencePlans)
      .where(eq(referencePlans.id, id))
      .get();
    if (!record) throw new Error('Unknown reference import plan');
    return ReferencePlanSchema.parse(record.body);
  }

  plans() {
    return this.db
      .select()
      .from(referencePlans)
      .all()
      .map((record) => ReferencePlanSchema.parse(record.body));
  }

  approve({
    id,
    revision,
    isApproved,
    createJobs,
  }: {
    id: string;
    revision: string;
    isApproved: boolean;
    createJobs: (plan: ReferenceImportPlan) => Array<{
      id: string;
      sourceId: string;
      collectionId: string;
      collectionIds: string[];
    }>;
  }) {
    if (!isApproved) throw new Error('Explicit user approval is required');
    return transaction(this.db, () => {
      const plan = this.plan(id);
      if (plan.revision !== revision)
        throw new Error(
          'Import plan revision does not match the reviewed plan',
        );
      if (plan.approvedAt) return plan;
      if (Date.now() >= Date.parse(plan.expiresAt))
        throw new Error('Import plan expired; prepare and review another plan');
      const jobs = createJobs(plan);
      for (const job of jobs)
        this.db
          .insert(plannedSources)
          .values({
            sourceId: job.sourceId,
            collectionId: job.collectionId,
            collectionIds: job.collectionIds,
            discoveryId: plan.discoveryId,
          })
          .onConflictDoUpdate({
            target: plannedSources.sourceId,
            set: {
              discoveryId: plan.discoveryId,
              collectionId: job.collectionId,
              collectionIds: job.collectionIds,
            },
          })
          .run();
      const approved = {
        ...plan,
        approvedAt: new Date().toISOString(),
        jobIds: jobs.map((job) => job.id),
      };
      this.db
        .update(referencePlans)
        .set({ body: approved })
        .where(eq(referencePlans.id, id))
        .run();
      this.db
        .insert(connectorOnboarding)
        .values({
          provider: referenceProvider(plan.profile),
          state: 'complete',
          offeredAt: null,
          remindAt: null,
        })
        .onConflictDoUpdate({
          target: connectorOnboarding.provider,
          set: { state: 'complete', remindAt: null },
        })
        .run();
      return approved;
    });
  }

  sourcePlan(sourceId: string) {
    return (
      this.db
        .select()
        .from(plannedSources)
        .where(eq(plannedSources.sourceId, sourceId))
        .get() ?? null
    );
  }

  sourceByUrl(url: string) {
    return (
      this.db
        .select({ sourceId: plannedSources.sourceId })
        .from(plannedSources)
        .innerJoin(sources, eq(sources.id, plannedSources.sourceId))
        .where(eq(sources.url, url))
        .get() ?? null
    );
  }

  isPlannedSource(sourceId: string) {
    return this.sourcePlan(sourceId) !== null;
  }

  onboarding(provider: ReferenceProvider = 'cosmos') {
    return (
      this.db
        .select()
        .from(connectorOnboarding)
        .where(eq(connectorOnboarding.provider, provider))
        .get() ?? {
        provider,
        state: 'pending' as const,
        offeredAt: null,
        remindAt: null,
      }
    );
  }

  updateOnboarding(
    action: ReferenceOnboardingAction,
    provider: ReferenceProvider = 'cosmos',
  ) {
    const state = action === 'dismiss' ? 'dismissed' : action;
    this.db
      .insert(connectorOnboarding)
      .values({
        provider,
        state: state === 'reset' ? 'pending' : state,
        offeredAt: null,
        remindAt:
          action === 'later'
            ? new Date(Date.now() + REFERENCE_REMINDER_DELAY_MS).toISOString()
            : null,
      })
      .onConflictDoUpdate({
        target: connectorOnboarding.provider,
        set: {
          state: state === 'reset' ? 'pending' : state,
          offeredAt: null,
          remindAt:
            action === 'later'
              ? new Date(Date.now() + REFERENCE_REMINDER_DELAY_MS).toISOString()
              : null,
        },
      })
      .run();
    return this.onboarding(provider);
  }

  notice(provider: ReferenceProvider = 'cosmos') {
    return transaction(this.db, () => {
      const state = this.onboarding(provider);
      if (
        state.state === 'complete' ||
        state.state === 'dismissed' ||
        state.offeredAt ||
        (state.remindAt && Date.now() < Date.parse(state.remindAt))
      )
        return null;
      this.db
        .insert(connectorOnboarding)
        .values({
          provider,
          state: 'pending',
          offeredAt: new Date().toISOString(),
          remindAt: null,
        })
        .onConflictDoUpdate({
          target: connectorOnboarding.provider,
          set: {
            state: 'pending',
            offeredAt: new Date().toISOString(),
            remindAt: null,
          },
        })
        .run();
      return {
        provider,
        message:
          provider === 'cosmos'
            ? 'Offer to connect a public Cosmos profile. Ask for its URL, discover collections, and present an import plan. Analysis consumes the selected agent usage allowance. Wait for explicit approval before importing.'
            : `Offer to connect ${provider} so Rivet can draw on saved inspiration across projects. Discover collections, complete OAuth if requested, then repeat discovery. Show the import plan and agent usage disclosure, and wait for explicit user approval.`,
        command:
          provider === 'cosmos'
            ? 'rivet profile discover <public-profile-url>'
            : `rivet profile discover ${provider}`,
        laterCommand: `rivet profile onboarding later --provider ${provider}`,
        dismissCommand: `rivet profile onboarding dismiss --provider ${provider}`,
      };
    });
  }
}
